import numpy as np
import pandas as pd


def case_report(df):
    out = {}
    for (w, s), g in df.groupby(['world', 'seed']):
        rep = {m: float(1 - g['mse_' + m].sum() / g['var_y'].sum()) for m in ('boost', 'mlp', 'ridge')}
        d = (g['mse_mlp'] - g['mse_boost']).to_numpy()
        t = float(d.mean() / (d.std(ddof=1) / np.sqrt(len(d))))
        rep['t'] = t
        rep['verdict'] = 'network' if t <= -2 else ('boosting' if t >= 2 else 'no change')
        out[(w, int(s))] = rep
    return out

