import numpy as np


def seeds_to_decide(diffs_by_seed):
    d = np.asarray(diffs_by_seed, dtype=float)
    for k in range(2, len(d) + 1):
        x = d[:k]
        sd = x.std(ddof=1)
        if sd == 0:
            if x.mean() != 0:
                return k
            continue
        if abs(x.mean()) / (sd / np.sqrt(k)) >= 2:
            return k
    return None

